#include <stdio.h>
#include <math.h>
int a,b,l;
double f(double x){return cos(x)*(b*tan(x)+a-l*sin(x));}
int main(){
    double w,S=0,T=acos(0),s,t;
    scanf("%d%d%d",&a,&b,&l);
    if(a>b){int tmp=a;a=b;b=tmp;}
    if(l<=b) w = l<=a?l:a;
    else{
        for(int i=255;i--;){
            s=(S*2+T)/3;
            t=(S+T*2)/3;
            if(f(s)<f(t)) T=t;
            else S=s;
        }
        w=f((S+T)/2);
        if(w<0){ printf("My poor head =("); return 0; }
    }
    printf("%.9f",w);
    return 0;
}

